        adopt(result);
        if (result.revision !== revision) {
          if (hasPendingSource()) {
            frozen = true;
            show("源码有未应用修改，请先下载源码备份");
            return;
          }
          if (dirty) {
            blocked = true;
            pause();
            await backup().catch(() => {
            });
            show("版本冲突 · 修改已保留，请下载 HTML", { retry: true, conflict: true });
            return;
          }
          await refresh();
          return;
        }
